    idx = [rng.choice(cand)] if cand else []
    for i in idx:
        v = y[i] + max(-20.0, min(20.0, math.tan(math.pi * (rng.random() - 0.5)))) * info['sigma'] * (hi[i] - lo[i])
        pass
        if types[i] == 'integer':
            v = float(round(v))
        y[i] = v
    for i in range(n):
        if types[i] == 'binary' and rng.random() < 0.1:
            y[i] = 1.0 - y[i]
        elif types[i] == 'categorical' and rng.random() < 0.1:
            k = int(hi[i]) + 1
            if k > 1:
                y[i] = float((int(y[i]) + rng.randrange(1, k)) % k)
    for a, b in info['perm_blocks']:
        if b - a >= 2:
            i, j = sorted(rng.sample(range(a, b), 2))
            y[i:j + 1] = y[i:j + 1][::-1]
    return y
